function blockPeaks(grid: number[][]): number[][] {
  const m = grid.length - 2;
  const out: number[][] = [];
  for (let i = 0; i < m; i++) {
    const row: number[] = [];
    for (let j = 0; j < m; j++) {
      let best = 0;
      for (let di = 0; di < 3; di++)
        for (let dj = 0; dj < 3; dj++) best = Math.max(best, grid[i + di][j + dj]);
      row.push(best);
    }
    out.push(row);
  }
  return out;
}

