function blockPeaks(grid: number[][]): number[][] {
  const n = grid.length, m = n - 2;
  // rowMax[r][j] = max of grid[r][j..j+2]
  const rowMax = grid.map(row => {
    const out: number[] = [];
    for (let j = 0; j < m; j++) out.push(Math.max(row[j], row[j + 1], row[j + 2]));
    return out;
  });
  const out: number[][] = [];
  for (let i = 0; i < m; i++) {
    const row: number[] = [];
    for (let j = 0; j < m; j++) row.push(Math.max(rowMax[i][j], rowMax[i + 1][j], rowMax[i + 2][j]));
    out.push(row);
  }
  return out;
}

